import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const dbPath = process.env.DB_PATH || path.join(process.cwd(), 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0
)`);
// Upgrade databases created by earlier task checkpoints.
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.id`);
const getProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const updateArchive = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = db.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const webRoot = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');

function sendJson(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') return sendJson(res, 200, { status: 'ok' });
  if (req.method === 'GET' && url.pathname === '/api/projects') return sendJson(res, 200, listProjects.all(url.searchParams.get('archived') === 'true' ? 1 : 0));
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (archiveMatch && req.method === 'PATCH') {
    let input;
    try { let body = ''; for await (const chunk of req) body += chunk; input = JSON.parse(body); }
    catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    if (typeof input.archived !== 'boolean') return sendJson(res, 400, { error: 'Invalid archive state' });
    const id = Number(archiveMatch[1]);
    if (!getProject.get(id)) return sendJson(res, 404, { error: 'Project not found' });
    updateArchive.run(input.archived ? 1 : 0, id);
    return sendJson(res, 200, { ok: true });
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let input;
    try { input = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof input.name === 'string' ? input.name.trim() : '';
    if (!name) return sendJson(res, 400, { error: 'Project name is required' });
    const result = insertProject.run(name);
    return sendJson(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    if (!getProject.get(Number(tasksMatch[1]))) return sendJson(res, 404, { error: 'Project not found' });
    return sendJson(res, 200, listTasks.all(Number(tasksMatch[1])));
  }
  if (tasksMatch && req.method === 'POST') {
    let input;
    try { let body = ''; for await (const chunk of req) body += chunk; input = JSON.parse(body); }
    catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const title = typeof input.title === 'string' ? input.title.trim() : '';
    if (!title) return sendJson(res, 400, { error: 'Task title is required' });
    const projectId = Number(tasksMatch[1]);
    const project = getProject.get(projectId);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(res, 409, { error: 'Archived projects cannot accept tasks' });
    const result = insertTask.run(projectId, title);
    return sendJson(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: 0 });
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    let input;
    try { let body = ''; for await (const chunk of req) body += chunk; input = JSON.parse(body); }
    catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    if (typeof input.completed !== 'boolean') return sendJson(res, 400, { error: 'Invalid completion state' });
    if (!getTask.get(taskId, projectId)) return sendJson(res, 404, { error: 'Task not found' });
    if (getProject.get(projectId).archived) return sendJson(res, 409, { error: 'Archived projects cannot be changed' });
    updateTask.run(input.completed ? 1 : 0, taskId, projectId);
    return sendJson(res, 200, { ok: true });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = getProject.get(Number(projectMatch[1]));
    return project ? sendJson(res, 200, project) : sendJson(res, 404, { error: 'Project not found' });
  }
  if (req.method === 'GET' && url.pathname.startsWith('/api/')) return sendJson(res, 404, { error: 'Not found' });

  const filename = url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname) ? 'index.html' : url.pathname === '/app.js' ? 'app.js' : url.pathname === '/styles.css' ? 'styles.css' : null;
  if (filename) {
    try {
      const content = await readFile(path.join(webRoot, filename));
      const type = filename.endsWith('.js') ? 'text/javascript' : filename.endsWith('.css') ? 'text/css' : 'text/html';
      res.writeHead(200, { 'Content-Type': `${type}; charset=utf-8` });
      return res.end(content);
    } catch { return sendJson(res, 500, { error: 'Unable to load application' }); }
  }
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

server.listen(Number(process.env.PORT) || 8080, '0.0.0.0');

const app = document.querySelector('#app');

async function request(url, options) {
  const response = await fetch(url, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Request failed');
  return result;
}

function heading(text) {
  const element = document.createElement('h1');
  element.textContent = text;
  return element;
}

async function render() {
  const match = window.location.pathname.match(/^\/projects\/(\d+)\/?$/);
  app.replaceChildren();
  if (match) {
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.append(heading(project.name));
      if (project.archived) {
        const status = document.createElement('p');
        status.textContent = 'Archived project';
        app.append(status);
      }
      const back = document.createElement('button');
      back.type = 'button';
      back.textContent = 'Projects';
      back.addEventListener('click', () => navigate('/'));
      app.append(back);

      const form = document.createElement('form');
      const label = document.createElement('label');
      label.htmlFor = 'task-title';
      label.textContent = 'Task title';
      const input = document.createElement('input');
      input.id = 'task-title';
      input.type = 'text';
      const submit = document.createElement('button');
      submit.type = 'submit';
      submit.textContent = 'Create task';
      submit.disabled = Boolean(project.archived);
      const alert = document.createElement('p');
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      form.append(label, input, submit, alert);
      app.append(form);

      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'task-filter';
      filterLabel.textContent = 'Task filter';
      const filter = document.createElement('select');
      filter.id = 'task-filter';
      for (const value of ['All', 'Open', 'Completed']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }
      app.append(filterLabel, filter);
      const list = document.createElement('section');
      list.setAttribute('aria-label', 'Tasks');
      app.append(list);

      async function loadTasks() {
        const tasks = await request(`/api/projects/${match[1]}/tasks`);
        list.replaceChildren();
        for (const task of tasks) {
          if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
          const row = document.createElement('div');
          row.dataset.testid = 'task-row';
          row.className = 'task-row';
          const title = document.createElement('span');
          title.textContent = task.title;
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = Boolean(task.completed);
          checkbox.disabled = Boolean(project.archived);
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            try {
              await request(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
              await loadTasks();
            } catch (error) { alert.textContent = error.message; alert.hidden = false; }
          });
          row.append(title, checkbox);
          list.append(row);
        }
      }
      filter.addEventListener('change', loadTasks);
      form.addEventListener('submit', async event => {
        event.preventDefault();
        alert.hidden = true;
        try {
          await request(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: input.value }) });
          input.value = '';
          filter.value = 'All';
          await loadTasks();
        } catch (error) { alert.textContent = error.message; alert.hidden = false; }
      });
      await loadTasks();
    } catch {
      app.append(heading('Project not found'));
      const back = document.createElement('button');
      back.type = 'button';
      back.textContent = 'Projects';
      back.addEventListener('click', () => navigate('/'));
      app.append(back);
    }
    return;
  }

  app.append(heading('Workboard'));
  const form = document.createElement('form');
  const label = document.createElement('label');
  label.htmlFor = 'project-name';
  label.textContent = 'Project name';
  const input = document.createElement('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.textContent = 'Create project';
  const alert = document.createElement('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  form.append(label, input, submit, alert);
  app.append(form);
  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'project-filter';
  filterLabel.textContent = 'Project filter';
  const filter = document.createElement('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    filter.append(option);
  }
  app.append(filterLabel, filter);
  const list = document.createElement('section');
  list.setAttribute('aria-label', 'Projects');
  app.append(list);

  async function loadProjects() {
    const archived = filter.value === 'Archived';
    const projects = await request(`/api/projects?archived=${archived}`);
    list.replaceChildren();
    for (const project of projects) {
      const row = document.createElement('div');
      row.dataset.testid = 'project-row';
      row.className = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      const open = document.createElement('button');
      open.type = 'button';
      open.textContent = 'Open project';
      open.addEventListener('click', () => navigate(`/projects/${project.id}`));
      const summary = document.createElement('span');
      summary.dataset.testid = 'project-summary';
      summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
      const archive = document.createElement('button');
      archive.type = 'button';
      archive.textContent = archived ? 'Restore project' : 'Archive project';
      archive.addEventListener('click', async () => {
        try {
          await request(`/api/projects/${project.id}/archive`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !archived }) });
          await loadProjects();
        } catch (error) { alert.textContent = error.message; alert.hidden = false; }
      });
      row.append(name, summary, open, archive);
      list.append(row);
    }
  }
  filter.addEventListener('change', loadProjects);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    alert.hidden = true;
    try {
      await request('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
      input.value = '';
      await loadProjects();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });
  try { await loadProjects(); } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
}

